      const result = job.comparison || {}, arms = result.arms || {}, completed = result.status === 'complete', comparable = completed && result.comparable;
      const left = records('candidates').find(c => c.id === arms.price_only?.candidate_id), right = records('candidates').find(c => c.id === arms.price_news?.candidate_id);
      return `<section class="box comparison-card"><div class="section-title"><span>同条件新闻输入对照 · ${short(job.id)}</span>${tag(comparable ? '完整 / 可比较' : completed ? '不满足可比性' : ['failed', 'cancelled'].includes(job.status) ? '对照未完成' : '双臂计算中', comparable ? 'teal' : 'gold')}</div><div class="comparison-protocol">${esc(job.config.symbol)} · ${TYPES[job.config.kind]} · ${esc(job.config.start)} → ${esc(job.config.end)} · seed ${job.config.parameters.seed}<br>同一行情快照、费用、资金、参数与时序划分；仅改变 4 列新闻输入。</div><div class="comparison-arms">${[['price_only', '仅价格', left, 'gold'], ['price_news', '价格＋新闻', right, 'teal']].map(([key, label, candidate, color]) => { const arm = arms[key] || {}, metrics = arm.metrics || candidate?.metrics; return `<div class="comparison-arm ${color}"><div class="between"><h3>${label}</h3>${statusTag(arm.status === 'pending' ? 'queued' : arm.status || 'queued')}</div><div class="compare-cell"><label>历史评估收益率</label><strong class="${metrics?.net_return >= 0 ? 'positive' : 'negative'}">${pct(metrics?.net_return)}</strong><p>最大回撤 ${finite(metrics?.max_drawdown) ? num(Math.abs(metrics.max_drawdown) * 100) + '%' : '—'} · ${metrics?.trades ?? '—'} 笔交易</p></div><p class="hint">${key === 'price_news' ? '6 列价格 + 4 列 log1p 新闻计数' : '6 列价格特征'}${candidate ? ` · 版本 ${short(candidate.id)}` : ''}</p>${arm.error ? `<div class="inline-error">${esc(arm.error)}</div>` : ''}${candidate ? `<button class="small" data-model="${esc(candidate.id)}" ${state.busy || current()?.selected_candidate_id === candidate.id ? 'disabled' : ''}>${current()?.selected_candidate_id === candidate.id ? '已选定此版本' : '选择此版本'}</button>` : `<p class="hint" style="margin-top:9px">${arm.status === 'succeeded' ? '本臂已算完；完整对照发布前不可启动。' : '结果由后端真实计算，不填充示例。'}</p>`}</div>`; }).join('')}</div>${comparable ? `<div class="comparison-delta">新闻 − 价格：收益差 <b class="${result.delta?.net_return >= 0 ? 'positive' : 'negative'}">${finite(result.delta?.net_return) ? signed(result.delta.net_return * 100) + ' 个百分点' : '—'}</b> · 最大回撤差 ${finite(result.delta?.max_drawdown) ? signed(result.delta.max_drawdown * 100) + ' 个百分点' : '—'} · 交易数差 ${signed(result.delta?.trades)}</div>${comparisonChart(left, right)}` : ''}${result.reasons?.length ? `<div class="inline-error">${esc(result.reasons.join('；'))}</div>` : ''}<div class="comparison-note">${result.news_snapshot_id ? `新闻快照 ${esc(result.news_snapshot_id)}。` : ''}GDELT 00/06/12/18 UTC 抽样，非全量新闻；历史可用时间采用批次 +1 小时假设。新闻模型可变差；该对照不证明因果收益改善。本轮没有额外新闻事件风控 B。</div></section>`;
