  const newsSymbol = () => state.newsSymbol || ((state.data?.capabilities.news_symbols || ['BTC/USDT', 'ETH/USDT']).includes(config().symbol) ? config().symbol : 'BTC/USDT');
  const coverageLabel = evidence => evidence?.coverage?.status === 'covered' ? evidence.event_ids?.length ? '截止前覆盖完整' : '覆盖完整 · 零匹配事件' : evidence?.coverage?.status === 'source_error' ? '新闻来源故障' : evidence?.coverage?.status === 'missing' ? '截止前覆盖不足' : '尚未检查';
  const eventLabel = value => ({ regulation: '监管', security: '安全', general: '一般事件', other: '其他事件' }[value] || value || '未分类');
  function factorTiles(evidence, compact = false) {
    return `<div class="factor-grid ${compact ? 'compact' : ''}">${NEWS_FEATURES.map(key => `<div class="factor-tile"><label>${NEWS_LABELS[key]}</label><span>${num(evidence?.values?.[key], 4)}</span>${compact ? '' : `<small>log1p · 原始计数 ${finite(evidence?.counts?.[key]) ? evidence.counts[key] : '—'}</small><code>${key}</code>`}</div>`).join('')}</div>`;
  }
